$ErrorActionPreference='Stop'
$root=Split-Path (Split-Path $PSScriptRoot -Parent) -Parent
function Assert($v,$r){if(!$v){throw $r}}
[xml]$native=Get-Content (Join-Path $root '../../Data/Config/blocks.xml') -Raw
[xml]$patch=Get-Content (Join-Path $root 'Config/_Rebirth/electrical_repair_blocks.xml') -Raw
$before=@{};foreach($b in $native.blocks.block){$p=$b.SelectSingleNode('property[@class="RepairItems"]');if($p){$before[$b.name]=$p.OuterXml}}
foreach($op in $patch.configs.ChildNodes){if($op.NodeType -ne [Xml.XmlNodeType]::Element){continue};$targets=@($native.SelectNodes($op.xpath));if($op.LocalName -eq 'remove'){Assert ($targets.Count -eq 3) 'three exact electrical parts targets';foreach($target in $targets){[void]$target.ParentNode.RemoveChild($target)}}elseif($op.LocalName -eq 'append'){foreach($target in $targets){foreach($child in $op.ChildNodes){if($child.NodeType -eq [Xml.XmlNodeType]::Element){[void]$target.AppendChild($native.ImportNode($child,$true))}}}}else{throw 'unsupported operation'}}
foreach($b in $native.blocks.block){$p=$b.SelectSingleNode('property[@class="RepairItems"]');if(!$p){continue};if($b.name -in @('generatorbank','batterybank','solarbank')){Assert ($null -eq $p.SelectSingleNode('property[@name="resourceElectricParts"]')) 'old electrical material removed';Assert ($null -ne $p.SelectSingleNode('property[@name="FuriousRamsayElectricalRepairKit"]')) 'kit consumer';Assert ($null -ne $p.SelectSingleNode('property[@name="resourceForgedIron"]')) 'structural repair retained'}else{Assert ($p.OuterXml -eq $before[$b.name]) "unrelated repair changed $($b.name)"}}
[xml]$variants=Get-Content (Join-Path $root 'Config/_Rebirth/industrial_power_blocks.xml') -Raw;foreach($b in $variants.configs.append.block){Assert ($b.SelectSingleNode('property[@name="Extends"]').value -in @('generatorbank','batterybank')) 'industrial inherits consumer';Assert ($null -eq $b.SelectSingleNode('property[@class="RepairItems"]')) 'no industrial override bypass'}
[xml]$recipe=Get-Content (Join-Path $root 'Config/_Rebirth/electrical_repair_recipes.xml') -Raw;Assert ($recipe.configs.append.recipe.ingredient.Count -eq 3) 'recipe complete'
[xml]$caps=Get-Content (Join-Path $root 'Config/_Survivor/capabilities.xml') -Raw;Assert ($null -ne $caps.SelectSingleNode('//capability[@target_id="FuriousRamsayElectricalRepairKit"]/requires_all/knowledge[@id="recipe.FuriousRamsayElectricalRepairKit"]')) 'exact knowledge'
$service=Get-Content (Join-Path $root 'Scripts/Survivor/Progression/RebirthInfrastructureWorkService.cs') -Raw;Assert (!$service.Contains('FuriousRamsayElectricalRepairKit')) 'no lifecycle servicing replacement';foreach($id in @('rebirthElectricalFuse','rebirthElectricalWiringHarness','rebirthElectricalTerminalBlock')){Assert ($service.Contains('ItemClass.GetItem("'+$id+'"')) 'service components retained'}
[xml]$entry=Get-Content (Join-Path $root 'Config/blocks.xml') -Raw;Assert ($null -ne $entry.SelectSingleNode('/configs/conditional/if[@cond="character_progression(''Rebirth'')"]/include[@filename="_Rebirth/electrical_repair_blocks.xml"]')) 'REBIRTH scope'
'PASS electrical kit scoped XML:3power-bank parents+2industrial inherited consumers; unrelated physical repairs unchanged; structural parts retained; exact recipe gate; servicing components untouched. Native repair consumption not exercised.'